// ResourceManager.ts
import { _decorator, resources, Asset, error, JsonAsset, Prefab, SpriteFrame } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('ResourceManager')
export class ResourceManager {
    private static _instance: ResourceManager;
    private loadedResources = {
        textures: new Map<string, SpriteFrame>(),    // 六边形地形贴图
        prefabs: new Map<string, Prefab>(),          // 六边形单元格/角色预制体
        configs: new Map<string, any>()              // 地图/角色配置数据
    };

    public static get Instance() {
        if (!this._instance) {
            this._instance = new ResourceManager();
        }
        return this._instance;
    }

    /**
     * 预加载所有基础资源
     * @param progressCallback 加载进度回调 (0-1)
     * @param completeCallback 完成回调
     */
    public preloadEssentialResources(
        progressCallback: (progress: number) => void,
        completeCallback: () => void
    ) {
        const loadTasks = [
            this.loadDir("textures/hex_tiles", "textures"),
            this.loadDir("prefabs/hex", "prefabs"),
            this.loadDir("config/map", "configs")
        ];

        let completedCount = 0;
        const totalTasks = loadTasks.length;

        loadTasks.forEach(task => {
            task.then(() => {
                completedCount++;
                const progress = completedCount / totalTasks;
                progressCallback(progress);
                if (completedCount === totalTasks) {
                    completeCallback();
                }
            }).catch(err => {
                error(`资源加载失败: ${err}`);
            });
        });
    }

    /**
     * 动态加载单个资源
     * @param path resources下相对路径
     * @param type 资源类型
     */
    public async loadRes<T extends Asset>(path: string, type: new () => T): Promise<T> {
        return new Promise((resolve, reject) => {
            resources.load(path, type, (err, asset) => {
                if (err) {
                    error(`加载失败: ${path}`, err);
                    reject(err);
                } else {
                    this.cacheResource(path, asset);
                    resolve(asset as T);
                }
            });
        });
    }

    // 获取已加载资源
    public getTexture(name: string): SpriteFrame | undefined {
        return this.loadedResources.textures.get(name);
    }

    public getHexPrefab(name: string): Prefab | undefined {
        return this.loadedResources.prefabs.get(name);
    }

    public getMapConfig(name: string): any {
        return this.loadedResources.configs.get(name);
    }

    private async loadDir(path: string, category: "textures" | "prefabs" | "configs") {
        return new Promise<void>((resolve, reject) => {
            resources.loadDir(path, (err, assets) => {
                if (err) {
                    reject(err);
                    return;
                }

                assets.forEach(asset => {
                    const assetName = this.getAssetName(asset);
                    if (assetName) {
                        this.loadedResources[category].set(assetName, asset);
                    }
                });
                resolve();
            });
        });
    }

    private cacheResource(path: string, asset: Asset) {
        const assetName = this.getAssetName(asset);
        if (!assetName) return;

        if (asset instanceof SpriteFrame) {
            this.loadedResources.textures.set(assetName, asset);
        } else if (asset instanceof Prefab) {
            this.loadedResources.prefabs.set(assetName, asset);
        } else if (asset instanceof JsonAsset) {
            this.loadedResources.configs.set(assetName, asset.json);
        }
    }

    private getAssetName(asset: Asset): string | null {
        const path = asset.nativeUrl.split('/').pop() || '';
        return path.split('.')[0]; // 去除扩展名
    }
}